/*
 * English speaking drills (window.DRILLS), practised in #/speak with browser TTS/STT — no AI calls.
 *   shadow: { id: "drill-shadow-NNN", kind: "shadow", theme, level, en: "one sentence to listen & repeat (8-25 words)", vi: "nghĩa" }
 *   qa:     { id: "drill-qa-NNN", kind: "qa", theme, level, q: "interviewer question", seconds: 60|90|120,
 *             sample: "spoken sample answer, plain text, 80-200 words", phrases: ["useful phrase", ...] (3-6) }
 *   term:   { id: "drill-term-NNN", kind: "term", theme: "tech", level, term: "idempotent", say: "gợi ý đọc cho người Việt",
 *             wrong: "lỗi phát âm hay gặp", example: "one English sentence using the term" }
 * theme: intro | tech | behavioral | design | project | negotiation | smalltalk ; level: mid | senior | lead
 */
(window.DRILLS = window.DRILLS || []).push(
  { id: "drill-shadow-001", kind: "shadow", theme: "intro", level: "senior", en: "I am a backend engineer with eight years of experience building Java services for fintech products.", vi: "Tôi là kỹ sư backend với tám năm kinh nghiệm xây dựng dịch vụ Java cho sản phẩm fintech." },
  { id: "drill-shadow-002", kind: "shadow", theme: "intro", level: "mid", en: "My day to day work is mostly Spring Boot, PostgreSQL, and Kafka in production.", vi: "Công việc hằng ngày của tôi chủ yếu là Spring Boot, PostgreSQL và Kafka trên production." },
  { id: "drill-shadow-003", kind: "shadow", theme: "intro", level: "mid", en: "I enjoy turning vague requirements into simple and reliable backend designs.", vi: "Tôi thích biến yêu cầu mơ hồ thành thiết kế backend đơn giản và đáng tin cậy." },
  { id: "drill-shadow-004", kind: "shadow", theme: "intro", level: "mid", en: "I started as a junior developer and grew into owning services end to end.", vi: "Tôi bắt đầu là lập trình viên junior và dần sở hữu dịch vụ từ đầu đến cuối." },
  { id: "drill-shadow-005", kind: "shadow", theme: "intro", level: "senior", en: "What excites me most is solving problems that affect real users every day.", vi: "Điều khiến tôi hứng thú nhất là giải quyết vấn đề ảnh hưởng người dùng thật mỗi ngày." },
  { id: "drill-shadow-006", kind: "shadow", theme: "intro", level: "senior", en: "I work best when I can see the impact of my code in production metrics.", vi: "Tôi làm việc hiệu quả nhất khi thấy tác động của code trong chỉ số production." },
  { id: "drill-shadow-007", kind: "shadow", theme: "intro", level: "lead", en: "I have led a small team of four engineers for the past two years.", vi: "Tôi dẫn dắt nhóm nhỏ bốn kỹ sư trong hai năm qua." },
  { id: "drill-shadow-008", kind: "shadow", theme: "intro", level: "mid", en: "My background is mainly Java, but I am comfortable reading and debugging other codebases.", vi: "Nền tảng của tôi chủ yếu là Java, nhưng tôi thoải mái đọc và debug codebase khác." },
  { id: "drill-shadow-009", kind: "shadow", theme: "intro", level: "senior", en: "I care a lot about code quality, testing, and keeping systems observable in production.", vi: "Tôi rất quan tâm chất lượng code, kiểm thử và giữ hệ thống quan sát được trên production." },
  { id: "drill-shadow-010", kind: "shadow", theme: "intro", level: "senior", en: "I like environments where engineers are trusted to make decisions and own outcomes.", vi: "Tôi thích môi trường kỹ sư được tin tưởng ra quyết định và chịu trách nhiệm kết quả." },
  { id: "drill-shadow-011", kind: "shadow", theme: "intro", level: "senior", en: "Over the years I have learned to balance speed of delivery with long term maintainability.", vi: "Qua nhiều năm tôi học cách cân bằng tốc độ giao hàng với khả năng bảo trì lâu dài." },
  { id: "drill-shadow-012", kind: "shadow", theme: "intro", level: "senior", en: "I am looking for a role where I can grow into architecture while staying hands on.", vi: "Tôi tìm vị trí để phát triển lên kiến trúc sư trong khi vẫn trực tiếp làm code." },
  { id: "drill-shadow-013", kind: "shadow", theme: "intro", level: "senior", en: "My strongest skill is diagnosing production issues quickly and fixing them safely.", vi: "Kỹ năng mạnh nhất của tôi là chẩn đoán sự cố production nhanh và sửa an toàn." },
  { id: "drill-shadow-014", kind: "shadow", theme: "intro", level: "senior", en: "I enjoy mentoring junior engineers and helping them build confidence in their decisions.", vi: "Tôi thích hướng dẫn kỹ sư junior và giúp họ tự tin vào quyết định." },
  { id: "drill-shadow-015", kind: "shadow", theme: "intro", level: "senior", en: "I have worked in both startups and larger companies, so I adapt to different paces.", vi: "Tôi đã làm cả startup lẫn công ty lớn, nên thích nghi được nhiều nhịp độ." },
  { id: "drill-shadow-016", kind: "shadow", theme: "intro", level: "senior", en: "The projects I am proudest of are the ones that quietly reduced operational pain.", vi: "Những dự án tôi tự hào nhất là những cái âm thầm giảm đau đớn vận hành." },
  { id: "drill-shadow-017", kind: "shadow", theme: "intro", level: "mid", en: "I prefer honest feedback over politeness because it helps me improve faster.", vi: "Tôi thích phản hồi thẳng thắn hơn lịch sự vì giúp tôi cải thiện nhanh hơn." },
  { id: "drill-shadow-018", kind: "shadow", theme: "tech", level: "mid", en: "In Java, an interface defines a contract that multiple classes can implement differently.", vi: "Trong Java, interface định nghĩa hợp đồng mà nhiều lớp có thể implement khác nhau." },
  { id: "drill-shadow-019", kind: "shadow", theme: "tech", level: "mid", en: "A HashMap stores key value pairs and gives average constant time lookups.", vi: "HashMap lưu cặp key value và cho tra cứu thời gian trung bình hằng số." },
  { id: "drill-shadow-020", kind: "shadow", theme: "tech", level: "mid", en: "Spring Boot auto configuration reduces boilerplate by wiring beans based on classpath.", vi: "Auto configuration của Spring Boot giảm boilerplate bằng cách nối bean dựa trên classpath." },
  { id: "drill-shadow-021", kind: "shadow", theme: "tech", level: "mid", en: "Dependency injection lets you swap implementations without changing the calling code.", vi: "Dependency injection cho phép thay implementation mà không đổi code gọi." },
  { id: "drill-shadow-022", kind: "shadow", theme: "tech", level: "mid", en: "JPA entities map Java objects to database rows through annotations and metadata.", vi: "JPA entity ánh xạ object Java sang dòng database qua annotation và metadata." },
  { id: "drill-shadow-023", kind: "shadow", theme: "tech", level: "mid", en: "A database index speeds up reads but slows down writes and increases storage.", vi: "Index database tăng tốc đọc nhưng làm chậm ghi và tăng dung lượng lưu trữ." },
  { id: "drill-shadow-024", kind: "shadow", theme: "tech", level: "mid", en: "Transactions ensure that either all operations succeed or none of them do.", vi: "Transaction đảm bảo hoặc mọi thao tác thành công hoặc không có thao tác nào." },
  { id: "drill-shadow-025", kind: "shadow", theme: "tech", level: "senior", en: "Kafka keeps messages in ordered partitions so consumers can process them reliably.", vi: "Kafka giữ message trong partition có thứ tự để consumer xử lý đáng tin cậy." },
  { id: "drill-shadow-026", kind: "shadow", theme: "tech", level: "senior", en: "Idempotency means retrying the same request does not create duplicate side effects.", vi: "Idempotency nghĩa là retry cùng request không tạo tác dụng phụ trùng lặp." },
  { id: "drill-shadow-027", kind: "shadow", theme: "tech", level: "senior", en: "A circuit breaker stops calling a failing dependency to prevent cascading failures.", vi: "Circuit breaker ngừng gọi dependency lỗi để tránh lỗi lan truyền." },
  { id: "drill-shadow-028", kind: "shadow", theme: "tech", level: "senior", en: "Caching trades freshness for speed, so you must define clear invalidation rules.", vi: "Caching đánh đổi độ mới lấy tốc độ, nên phải định rõ quy tắc invalidate." },
  { id: "drill-shadow-029", kind: "shadow", theme: "tech", level: "senior", en: "Connection pooling reuses database connections to avoid expensive setup overhead.", vi: "Connection pooling tái sử dụng kết nối database để tránh overhead thiết lập đắt." },
  { id: "drill-shadow-030", kind: "shadow", theme: "tech", level: "senior", en: "Garbage collection frees unused memory automatically, but large heaps can pause threads.", vi: "Garbage collection giải phóng bộ nhớ không dùng tự động, nhưng heap lớn có thể pause thread." },
  { id: "drill-shadow-031", kind: "shadow", theme: "tech", level: "mid", en: "Horizontal scaling adds more machines, while vertical scaling makes one machine bigger.", vi: "Scale ngang thêm máy, scale dọc làm một máy lớn hơn." },
  { id: "drill-shadow-032", kind: "shadow", theme: "tech", level: "senior", en: "Eventual consistency means data converges over time instead of being immediately identical.", vi: "Eventual consistency nghĩa là dữ liệu hội tụ theo thời gian thay vì giống ngay lập tức." },
  { id: "drill-shadow-033", kind: "shadow", theme: "tech", level: "senior", en: "Rate limiting protects services by rejecting or delaying requests above a threshold.", vi: "Rate limiting bảo vệ dịch vụ bằng cách từ chối hoặc trì hoãn request vượt ngưỡng." },
  { id: "drill-shadow-034", kind: "shadow", theme: "tech", level: "senior", en: "Observability combines logs, metrics, and traces to explain system behavior in production.", vi: "Observability kết hợp log, metric và trace để giải thích hành vi hệ thống trên production." },
  { id: "drill-shadow-035", kind: "shadow", theme: "tech", level: "senior", en: "A load balancer distributes traffic across instances to improve availability and throughput.", vi: "Load balancer phân phối traffic qua các instance để cải thiện availability và throughput." },
  { id: "drill-shadow-036", kind: "shadow", theme: "design", level: "senior", en: "Let me think out loud while I work through the requirements with you.", vi: "Để tôi suy nghĩ thành tiếng trong khi làm rõ yêu cầu cùng bạn." },
  { id: "drill-shadow-037", kind: "shadow", theme: "design", level: "senior", en: "Before designing, can I clarify the expected traffic and consistency requirements?", vi: "Trước khi thiết kế, tôi có thể làm rõ traffic kỳ vọng và yêu cầu consistency không?" },
  { id: "drill-shadow-038", kind: "shadow", theme: "design", level: "senior", en: "I would start by estimating the read and write volume per second.", vi: "Tôi sẽ bắt đầu ước lượng khối lượng đọc và ghi mỗi giây." },
  { id: "drill-shadow-039", kind: "shadow", theme: "design", level: "lead", en: "The main trade off here is between consistency and availability under network partitions.", vi: "Trade off chính ở đây là giữa consistency và availability khi partition mạng." },
  { id: "drill-shadow-040", kind: "shadow", theme: "design", level: "senior", en: "I would keep the first version simple and add complexity only when metrics justify it.", vi: "Tôi giữ phiên bản đầu đơn giản và thêm phức tạp chỉ khi metric biện minh." },
  { id: "drill-shadow-041", kind: "shadow", theme: "design", level: "senior", en: "Let me sketch the data flow before talking about specific technologies.", vi: "Để tôi phác luồng dữ liệu trước khi nói về công nghệ cụ thể." },
  { id: "drill-shadow-042", kind: "shadow", theme: "design", level: "senior", en: "We can scale reads with caching and writes with partitioning by tenant.", vi: "Chúng ta scale đọc bằng cache và ghi bằng partition theo tenant." },
  { id: "drill-shadow-043", kind: "shadow", theme: "design", level: "senior", en: "I would rather accept eventual consistency than block users on a slow dependency.", vi: "Tôi thà chấp nhận eventual consistency còn hơn chặn người dùng vì dependency chậm." },
  { id: "drill-shadow-044", kind: "shadow", theme: "design", level: "senior", en: "The bottleneck is likely the database, so I would measure before optimizing anything.", vi: "Nút thắt cổ chai có lẽ là database, nên tôi sẽ đo trước khi tối ưu bất cứ thứ gì." },
  { id: "drill-shadow-045", kind: "shadow", theme: "design", level: "senior", en: "I would add an asynchronous queue to decouple the slow downstream service.", vi: "Tôi sẽ thêm queue bất đồng bộ để tách dịch vụ downstream chậm." },
  { id: "drill-shadow-046", kind: "shadow", theme: "design", level: "senior", en: "Let me consider failure modes, because the happy path is usually not the hard part.", vi: "Để tôi xem xét failure mode, vì happy path thường không phải phần khó." },
  { id: "drill-shadow-047", kind: "shadow", theme: "design", level: "senior", en: "We need to decide who owns the data and how other services access it.", vi: "Chúng ta cần quyết định ai sở hữu dữ liệu và service khác truy cập thế nào." },
  { id: "drill-shadow-048", kind: "shadow", theme: "design", level: "senior", en: "I would put a cache in front of the database with a short time to live.", vi: "Tôi sẽ đặt cache trước database với time to live ngắn." },
  { id: "drill-shadow-049", kind: "shadow", theme: "design", level: "senior", en: "A single source of truth prevents subtle bugs when multiple services update the same data.", vi: "Một nguồn dữ liệu duy nhất tránh lỗi tinh vi khi nhiều service cập nhật cùng dữ liệu." },
  { id: "drill-shadow-050", kind: "shadow", theme: "design", level: "senior", en: "I would monitor latency percentiles rather than averages to catch tail problems.", vi: "Tôi sẽ theo dõi percentile độ trễ thay vì trung bình để bắt vấn đề đuôi." },
  { id: "drill-shadow-051", kind: "shadow", theme: "design", level: "senior", en: "The design should degrade gracefully when a dependency becomes unavailable.", vi: "Thiết kế nên suy giảm nhẹ nhàng khi dependency không khả dụng." },
  { id: "drill-shadow-052", kind: "shadow", theme: "design", level: "senior", en: "I would document the assumptions now so we can revisit them later.", vi: "Tôi sẽ ghi lại giả định ngay để xem xét lại sau." },
  { id: "drill-shadow-053", kind: "shadow", theme: "project", level: "senior", en: "I led the migration of our monolith to microservices without downtime.", vi: "Tôi dẫn đầu di chuyển monolith sang microservices mà không downtime." },
  { id: "drill-shadow-054", kind: "shadow", theme: "project", level: "senior", en: "We reduced checkout latency from eight hundred milliseconds to under two hundred.", vi: "Chúng tôi giảm độ trễ checkout từ tám trăm mili giây xuống dưới hai trăm." },
  { id: "drill-shadow-055", kind: "shadow", theme: "project", level: "senior", en: "I designed the payment retry flow that cut failed transactions by forty percent.", vi: "Tôi thiết kế luồng retry thanh toán cắt giao dịch thất bại bốn mươi phần trăm." },
  { id: "drill-shadow-056", kind: "shadow", theme: "project", level: "senior", en: "My role was to own the order service and coordinate with three other teams.", vi: "Vai trò của tôi là sở hữu order service và phối hợp với ba team khác." },
  { id: "drill-shadow-057", kind: "shadow", theme: "project", level: "senior", en: "We introduced an outbox pattern and eliminated lost events in production.", vi: "Chúng tôi đưa vào outbox pattern và loại bỏ event mất trên production." },
  { id: "drill-shadow-058", kind: "shadow", theme: "project", level: "senior", en: "I built the reconciliation job that saved finance about six hours every day.", vi: "Tôi xây dựng job đối soát tiết kiệm finance khoảng sáu giờ mỗi ngày." },
  { id: "drill-shadow-059", kind: "shadow", theme: "project", level: "senior", en: "We cut incident count by thirty percent after adding better metrics and alerts.", vi: "Chúng tôi giảm số incident ba mươi phần trăm sau khi thêm metric và alert tốt hơn." },
  { id: "drill-shadow-060", kind: "shadow", theme: "project", level: "senior", en: "I refactored the legacy billing module and added tests without changing behavior.", vi: "Tôi refactor module billing legacy và thêm test mà không đổi hành vi." },
  { id: "drill-shadow-061", kind: "shadow", theme: "project", level: "senior", en: "We moved from manual deployments to automated pipelines with rollback support.", vi: "Chúng tôi chuyển từ deploy thủ công sang pipeline tự động có rollback." },
  { id: "drill-shadow-062", kind: "shadow", theme: "project", level: "senior", en: "I introduced contract tests between services to catch breaking changes early.", vi: "Tôi đưa contract test giữa các service để bắt breaking change sớm." },
  { id: "drill-shadow-063", kind: "shadow", theme: "project", level: "senior", en: "We improved cache hit rate from sixty to ninety percent by tuning keys.", vi: "Chúng tôi cải thiện cache hit rate từ sáu mươi lên chín mươi phần trăm bằng tuning key." },
  { id: "drill-shadow-064", kind: "shadow", theme: "project", level: "senior", en: "I owned the on call rotation and reduced mean time to recovery significantly.", vi: "Tôi phụ trách on call và giảm thời gian khôi phục trung bình đáng kể." },
  { id: "drill-shadow-065", kind: "shadow", theme: "project", level: "senior", en: "We handled peak traffic of ten thousand requests per second during a sale.", vi: "Chúng tôi xử lý peak traffic mười nghìn request mỗi giây trong đợt sale." },
  { id: "drill-shadow-066", kind: "shadow", theme: "project", level: "lead", en: "I led the database migration with zero data loss across two regions.", vi: "Tôi dẫn đầu migration database không mất dữ liệu qua hai region." },
  { id: "drill-shadow-067", kind: "shadow", theme: "project", level: "senior", en: "We added idempotency keys to prevent duplicate charges during network retries.", vi: "Chúng tôi thêm idempotency key để tránh charge trùng khi retry mạng." },
  { id: "drill-shadow-068", kind: "shadow", theme: "project", level: "senior", en: "I wrote the runbooks that let new engineers resolve incidents independently.", vi: "Tôi viết runbook để kỹ sư mới tự xử lý sự cố độc lập." },
  { id: "drill-shadow-069", kind: "shadow", theme: "project", level: "senior", en: "The biggest win was reducing manual reconciliation work from hours to minutes.", vi: "Chiến thắng lớn nhất là giảm công việc đối soát thủ công từ giờ xuống phút." },
  { id: "drill-shadow-070", kind: "shadow", theme: "behavioral", level: "mid", en: "I once disagreed with a teammate about a design and we talked it through.", vi: "Tôi từng bất đồng với đồng đội về thiết kế và chúng tôi thảo luận kỹ." },
  { id: "drill-shadow-071", kind: "shadow", theme: "behavioral", level: "senior", en: "When a project failed, I focused on what we learned rather than blaming anyone.", vi: "Khi dự án thất bại, tôi tập trung vào điều học được thay vì đổ lỗi." },
  { id: "drill-shadow-072", kind: "shadow", theme: "behavioral", level: "senior", en: "I take ownership of my mistakes and communicate them early to stakeholders.", vi: "Tôi chịu trách nhiệm lỗi của mình và thông báo sớm cho stakeholder." },
  { id: "drill-shadow-073", kind: "shadow", theme: "behavioral", level: "senior", en: "I prefer to raise risks early instead of hoping they resolve themselves.", vi: "Tôi thích nêu risk sớm thay vì hy vọng nó tự giải quyết." },
  { id: "drill-shadow-074", kind: "shadow", theme: "behavioral", level: "senior", en: "Conflict is easier to resolve when both sides focus on the underlying problem.", vi: "Conflict dễ giải quyết hơn khi cả hai tập trung vào vấn đề gốc." },
  { id: "drill-shadow-075", kind: "shadow", theme: "behavioral", level: "mid", en: "I learned to ask for help instead of struggling alone for too long.", vi: "Tôi học cách xin giúp đỡ thay vì vật lộn một mình quá lâu." },
  { id: "drill-shadow-076", kind: "shadow", theme: "behavioral", level: "senior", en: "I give credit to the team when things go well and own failures myself.", vi: "Tôi ghi nhận team khi thành công và tự chịu thất bại." },
  { id: "drill-shadow-077", kind: "shadow", theme: "behavioral", level: "senior", en: "I once pushed back on a feature that would have created a second source of truth.", vi: "Tôi từng phản đối tính năng sẽ tạo nguồn dữ liệu thứ hai." },
  { id: "drill-shadow-078", kind: "shadow", theme: "behavioral", level: "mid", en: "I handle pressure by breaking work into small steps and communicating progress.", vi: "Tôi xử lý áp lực bằng cách chia nhỏ công việc và thông báo tiến độ." },
  { id: "drill-shadow-079", kind: "shadow", theme: "behavioral", level: "mid", en: "I ask clarifying questions before starting work to avoid building the wrong thing.", vi: "Tôi hỏi làm rõ trước khi bắt đầu để tránh xây sai thứ." },
  { id: "drill-shadow-080", kind: "shadow", theme: "behavioral", level: "senior", en: "I try to separate the person from the problem during difficult conversations.", vi: "Tôi cố tách con người khỏi vấn đề trong các cuộc trò chuyện khó." },
  { id: "drill-shadow-081", kind: "shadow", theme: "behavioral", level: "senior", en: "When priorities change, I adapt quickly and communicate the impact on timelines.", vi: "Khi ưu tiên thay đổi, tôi thích nghi nhanh và thông báo ảnh hưởng timeline." },
  { id: "drill-shadow-082", kind: "shadow", theme: "behavioral", level: "senior", en: "I believe most conflicts come from unclear expectations rather than bad intent.", vi: "Tôi tin hầu hết conflict đến từ kỳ vọng không rõ ràng chứ không phải ý xấu." },
  { id: "drill-shadow-083", kind: "shadow", theme: "behavioral", level: "senior", en: "I document decisions so future teammates understand why we chose a path.", vi: "Tôi ghi lại quyết định để đồng đội tương lai hiểu vì sao chọn hướng đó." },
  { id: "drill-shadow-084", kind: "shadow", theme: "behavioral", level: "senior", en: "I stay calm in incidents by following the runbook and assigning clear roles.", vi: "Tôi giữ bình tĩnh trong sự cố bằng cách theo runbook và phân công rõ ràng." },
  { id: "drill-shadow-085", kind: "shadow", theme: "behavioral", level: "senior", en: "I mentor by asking questions rather than giving answers directly.", vi: "Tôi hướng dẫn bằng cách đặt câu hỏi thay vì đưa đáp án trực tiếp." },
  { id: "drill-shadow-086", kind: "shadow", theme: "behavioral", level: "senior", en: "I measure success by outcomes for users, not by how much code I wrote.", vi: "Tôi đo thành công bằng kết quả cho người dùng, không phải lượng code viết." },
  { id: "drill-shadow-087", kind: "shadow", theme: "negotiation", level: "senior", en: "My expected salary is based on market rate and the scope of this role.", vi: "Mức lương kỳ vọng của tôi dựa trên thị trường và phạm vi vị trí này." },
  { id: "drill-shadow-088", kind: "shadow", theme: "negotiation", level: "senior", en: "I would like to understand the full compensation package before discussing numbers.", vi: "Tôi muốn hiểu toàn bộ gói đãi ngộ trước khi thảo luận con số." },
  { id: "drill-shadow-089", kind: "shadow", theme: "negotiation", level: "mid", en: "My notice period is one month, but I can negotiate with my current employer.", vi: "Thời gian báo trước của tôi là một tháng, nhưng có thể thương lượng với công ty hiện tại." },
  { id: "drill-shadow-090", kind: "shadow", theme: "negotiation", level: "mid", en: "I am flexible on start date as long as I can hand over my current work.", vi: "Tôi linh hoạt ngày bắt đầu nếu có thể bàn giao công việc hiện tại." },
  { id: "drill-shadow-091", kind: "shadow", theme: "negotiation", level: "senior", en: "I am interested in the role and would like to discuss the offer details.", vi: "Tôi quan tâm vị trí và muốn thảo luận chi tiết offer." },
  { id: "drill-shadow-092", kind: "shadow", theme: "negotiation", level: "senior", en: "Could you clarify how the bonus and equity components are calculated?", vi: "Bạn có thể làm rõ cách tính bonus và equity không?" },
  { id: "drill-shadow-093", kind: "shadow", theme: "negotiation", level: "senior", en: "I appreciate the offer and would like a day to review it carefully.", vi: "Tôi trân trọng offer và muốn một ngày để xem xét kỹ." },
  { id: "drill-shadow-094", kind: "shadow", theme: "negotiation", level: "senior", en: "My current total compensation includes base salary, bonus, and stock options.", vi: "Tổng thu nhập hiện tại của tôi gồm lương cơ bản, bonus và stock option." },
  { id: "drill-shadow-095", kind: "shadow", theme: "negotiation", level: "mid", en: "I am looking for growth opportunities as much as a salary increase.", vi: "Tôi tìm cơ hội phát triển nhiều như tăng lương." },
  { id: "drill-shadow-096", kind: "shadow", theme: "negotiation", level: "senior", en: "Is there flexibility on the base salary or on the signing bonus?", vi: "Có linh hoạt về lương cơ bản hoặc signing bonus không?" },
  { id: "drill-shadow-097", kind: "shadow", theme: "negotiation", level: "senior", en: "I need to consider the role, team, and long term career fit before deciding.", vi: "Tôi cần cân nhắc vị trí, team và phù hợp dài hạn trước khi quyết định." },
  { id: "drill-shadow-098", kind: "shadow", theme: "negotiation", level: "mid", en: "Could you share the typical career path for someone in this position?", vi: "Bạn có thể chia sẻ lộ trình sự nghiệp điển hình cho vị trí này không?" },
  { id: "drill-shadow-099", kind: "shadow", theme: "negotiation", level: "senior", en: "I would prefer to discuss salary after we both agree on the role fit.", vi: "Tôi muốn thảo luận lương sau khi cả hai đồng ý về phù hợp vị trí." },
  { id: "drill-shadow-100", kind: "shadow", theme: "negotiation", level: "senior", en: "What does success look like in the first ninety days for this role?", vi: "Thành công trông như thế nào trong chín mươi ngày đầu cho vị trí này?" },
  { id: "drill-shadow-101", kind: "shadow", theme: "negotiation", level: "senior", en: "I am open to a lower base if the overall package and growth are strong.", vi: "Tôi mở với lương cơ bản thấp hơn nếu gói tổng thể và phát triển mạnh." },
  { id: "drill-shadow-102", kind: "shadow", theme: "negotiation", level: "senior", en: "Could we revisit compensation after a performance review in six months?", vi: "Chúng ta có thể xem lại đãi ngộ sau đánh giá hiệu suất sáu tháng không?" },
  { id: "drill-shadow-103", kind: "shadow", theme: "negotiation", level: "mid", en: "Thank you for the offer, I am excited about the opportunity to join.", vi: "Cảm ơn offer, tôi rất hứng thú cơ hội gia nhập." },
  { id: "drill-shadow-104", kind: "shadow", theme: "smalltalk", level: "mid", en: "Thank you for taking the time to speak with me today.", vi: "Cảm ơn bạn đã dành thời gian nói chuyện với tôi hôm nay." },
  { id: "drill-shadow-105", kind: "shadow", theme: "smalltalk", level: "mid", en: "Could you repeat the question, please? I want to make sure I understand.", vi: "Bạn có thể nhắc lại câu hỏi không? Tôi muốn chắc mình hiểu đúng." },
  { id: "drill-shadow-106", kind: "shadow", theme: "smalltalk", level: "mid", en: "Let me take a moment to think before I answer.", vi: "Để tôi dành một chút thời gian suy nghĩ trước khi trả lời." },
  { id: "drill-shadow-107", kind: "shadow", theme: "smalltalk", level: "mid", en: "That is a great question, and I want to give it a thoughtful answer.", vi: "Đó là câu hỏi hay, và tôi muốn trả lời có suy nghĩ." },
  { id: "drill-shadow-108", kind: "shadow", theme: "smalltalk", level: "mid", en: "Could you clarify what you mean by scalable in this context?", vi: "Bạn có thể làm rõ ý scalable trong ngữ cảnh này không?" },
  { id: "drill-shadow-109", kind: "shadow", theme: "smalltalk", level: "mid", en: "I am not sure I caught that, could you say it again more slowly?", vi: "Tôi không chắc mình nghe rõ, bạn có thể nói lại chậm hơn không?" },
  { id: "drill-shadow-110", kind: "shadow", theme: "smalltalk", level: "mid", en: "Before we start, may I ask how long this interview will take?", vi: "Trước khi bắt đầu, tôi có thể hỏi buổi phỏng vấn mất bao lâu không?" },
  { id: "drill-shadow-111", kind: "shadow", theme: "smalltalk", level: "mid", en: "I appreciate the opportunity to learn more about your team and product.", vi: "Tôi trân trọng cơ hội tìm hiểu thêm về team và sản phẩm của bạn." },
  { id: "drill-shadow-112", kind: "shadow", theme: "smalltalk", level: "mid", en: "Do you have any questions for me about my background or experience?", vi: "Bạn có câu hỏi nào cho tôi về nền tảng hoặc kinh nghiệm không?" },
  { id: "drill-shadow-113", kind: "shadow", theme: "smalltalk", level: "mid", en: "Thank you for the detailed explanation, that helps me understand better.", vi: "Cảm ơn giải thích chi tiết, điều đó giúp tôi hiểu rõ hơn." },
  { id: "drill-shadow-114", kind: "shadow", theme: "smalltalk", level: "mid", en: "I enjoyed this conversation and I am excited about the next steps.", vi: "Tôi thích cuộc trò chuyện này và hào hứng với các bước tiếp theo." },
  { id: "drill-shadow-115", kind: "shadow", theme: "smalltalk", level: "mid", en: "Could you tell me a bit about the team I would be joining?", vi: "Bạn có thể kể một chút về team tôi sẽ gia nhập không?" },
  { id: "drill-shadow-116", kind: "shadow", theme: "smalltalk", level: "mid", en: "What is the biggest challenge your team is facing right now?", vi: "Thách thức lớn nhất team bạn đang đối mặt hiện tại là gì?" },
  { id: "drill-shadow-117", kind: "shadow", theme: "smalltalk", level: "mid", en: "I would love to hear more about how decisions are made on your team.", vi: "Tôi muốn nghe thêm về cách ra quyết định trong team bạn." },
  { id: "drill-shadow-118", kind: "shadow", theme: "smalltalk", level: "mid", en: "Is there anything in my background that concerns you so far?", vi: "Có điều gì trong nền tảng của tôi khiến bạn lo ngại cho đến giờ không?" },
  { id: "drill-shadow-119", kind: "shadow", theme: "smalltalk", level: "mid", en: "Thank you for your time today, I really enjoyed our discussion.", vi: "Cảm ơn thời gian của bạn hôm nay, tôi rất thích cuộc thảo luận." },
  { id: "drill-shadow-120", kind: "shadow", theme: "smalltalk", level: "mid", en: "I look forward to hearing from you and learning about next steps.", vi: "Tôi mong nhận phản hồi từ bạn và biết các bước tiếp theo." },
  { id: "drill-shadow-121", kind: "shadow", theme: "intro", level: "mid", en: "Hi, I am the backend engineer who will be working with you on this project.", vi: "Chào bạn, tôi là kỹ sư backend sẽ làm việc cùng bạn trong dự án này." },
  { id: "drill-shadow-122", kind: "shadow", theme: "smalltalk", level: "mid", en: "Great to meet you, and thank you for trusting me with this work.", vi: "Rất vui được gặp bạn, và cảm ơn bạn đã tin tưởng công việc này cho tôi." },
  { id: "drill-shadow-123", kind: "shadow", theme: "project", level: "senior", en: "Before we start, I would like to confirm the scope and the main goals.", vi: "Trước khi bắt đầu, tôi muốn xác nhận phạm vi và mục tiêu chính." },
  { id: "drill-shadow-124", kind: "shadow", theme: "smalltalk", level: "mid", en: "Could you give me an example of how this feature should behave?", vi: "Bạn có thể cho tôi một ví dụ tính năng này nên hoạt động thế nào không?" },
  { id: "drill-shadow-125", kind: "shadow", theme: "project", level: "senior", en: "I estimate this will take about two weeks, including testing and review.", vi: "Tôi ước lượng việc này mất khoảng hai tuần, bao gồm kiểm thử và review." },
  { id: "drill-shadow-126", kind: "shadow", theme: "project", level: "mid", en: "This is a rough estimate, and I will update you as I learn more.", vi: "Đây là ước lượng sơ bộ, và tôi sẽ cập nhật cho bạn khi biết thêm." },
  { id: "drill-shadow-127", kind: "shadow", theme: "project", level: "senior", en: "I need to let you know that the delivery will be slightly delayed.", vi: "Tôi cần để bạn biết rằng giao hàng sẽ bị trễ một chút." },
  { id: "drill-shadow-128", kind: "shadow", theme: "negotiation", level: "mid", en: "The delay is caused by an external API that is not responding reliably.", vi: "Sự trễ do một API bên ngoài không phản hồi ổn định." },
  { id: "drill-shadow-129", kind: "shadow", theme: "negotiation", level: "senior", en: "Could we move the deadline by three days so I can finish properly?", vi: "Chúng ta có thể đẩy deadline thêm ba ngày để tôi hoàn thành đúng cách không?" },
  { id: "drill-shadow-130", kind: "shadow", theme: "negotiation", level: "mid", en: "I need a bit more time to make sure the quality is good enough.", vi: "Tôi cần thêm chút thời gian để chắc chắn chất lượng đủ tốt." },
  { id: "drill-shadow-131", kind: "shadow", theme: "negotiation", level: "senior", en: "I cannot take on extra work this week without affecting current commitments.", vi: "Tôi không thể nhận thêm công việc tuần này mà không ảnh hưởng cam kết hiện tại." },
  { id: "drill-shadow-132", kind: "shadow", theme: "smalltalk", level: "mid", en: "I would love to help, but my schedule is full until next month.", vi: "Tôi rất muốn giúp, nhưng lịch trình của tôi đầy cho đến tháng sau." },
  { id: "drill-shadow-133", kind: "shadow", theme: "smalltalk", level: "mid", en: "Thank you for the feedback, and please let me know what to improve.", vi: "Cảm ơn phản hồi của bạn, và vui lòng cho tôi biết cần cải thiện gì." },
  { id: "drill-shadow-134", kind: "shadow", theme: "project", level: "senior", en: "I have finished the first version, and I would appreciate your review.", vi: "Tôi đã hoàn thành phiên bản đầu, mong bạn dành thời gian góp ý." },
  { id: "drill-shadow-135", kind: "shadow", theme: "project", level: "mid", en: "I have completed the API design and am starting the implementation now.", vi: "Tôi đã hoàn thành thiết kế API và đang bắt đầu triển khai ngay bây giờ." },
  { id: "drill-shadow-136", kind: "shadow", theme: "project", level: "senior", en: "We are halfway through the sprint, and all tasks are on track so far.", vi: "Chúng ta đã đi được nửa sprint, và mọi việc đang đúng tiến độ cho đến giờ." },
  { id: "drill-shadow-137", kind: "shadow", theme: "project", level: "senior", en: "I am sorry for the outage, and we are fixing it right now.", vi: "Tôi xin lỗi về sự cố gián đoạn, và chúng tôi đang khắc phục ngay bây giờ." },
  { id: "drill-shadow-138", kind: "shadow", theme: "negotiation", level: "mid", en: "Please accept my apologies for the delay and any trouble it caused.", vi: "Xin hãy nhận lời xin lỗi của tôi vì sự chậm trễ và những bất tiện đã gây ra." },
  { id: "drill-shadow-139", kind: "shadow", theme: "project", level: "senior", en: "I suggest we add a cache in front of the slow database query.", vi: "Tôi đề xuất thêm cache phía trước truy vấn cơ sở dữ liệu đang chậm." },
  { id: "drill-shadow-140", kind: "shadow", theme: "negotiation", level: "mid", en: "Another option is to run the heavy job during off-peak hours.", vi: "Một lựa chọn khác là chạy công việc nặng trong giờ ít truy cập." },
{ id: "drill-shadow-141", kind: "shadow", theme: "tech", level: "senior", en: "Transaction isolation level determines how concurrent transactions see each other's changes.", vi: "Mức cách ly transaction xác định giao dịch đồng thời nhìn thấy thay đổi của nhau như thế nào." },
  { id: "drill-shadow-142", kind: "shadow", theme: "tech", level: "mid", en: "A database index is like a book's table of contents that lets the engine find rows without scanning everything.", vi: "Một index database giống như mục lục của sách, giúp engine tìm dòng mà không cần quét toàn bộ bảng." },
  { id: "drill-shadow-143", kind: "shadow", theme: "tech", level: "senior", en: "Redis caches frequently accessed data in memory so the application avoids hitting the slower database on every request.", vi: "Redis cache dữ liệu thường xuyên truy cập vào bộ nhớ trong, giúp ứng dụng tránh gọi database chậm mỗi request." },
  { id: "drill-shadow-144", kind: "shadow", theme: "tech", level: "senior", en: "Kafka partitions allow parallel consumers to read different segments of a topic without competing for the same records.", vi: "Kafka partition cho phép consumer song song đọc các phân khúc khác nhau của topic mà không cạnh tranh cùng record." },
  { id: "drill-shadow-145", kind: "shadow", theme: "tech", level: "senior", en: "A thread pool limits the number of concurrent workers so the application does not collapse under heavy load.", vi: "Một thread pool giới hạn số worker concurrently để ứng dụng không sụp đổ dưới tải nặng." },
  { id: "drill-shadow-146", kind: "shadow", theme: "tech", level: "mid", en: "The garbage collector reclaims objects that are no longer referenced, freeing memory for new allocations.", vi: "Garbage collector thu hồi các object không còn được tham chiếu, giải phóng bộ nhớ cho các allocation mới." },
  { id: "drill-shadow-147", kind: "shadow", theme: "tech", level: "senior", en: "Connection pooling keeps database connections open and ready instead of creating a new one for every request.", vi: "Connection pooling giữ kết nối database mở và sẵn sàng thay vì tạo mới cho mỗi request." },
  { id: "drill-shadow-148", kind: "shadow", theme: "tech", level: "senior", en: "Idempotent consumers can safely reprocess the same message without producing duplicate results.", vi: "Consumer idempotent có thể xử lý lại an toàn cùng message mà không tạo kết quả trùng lặp." },
  { id: "drill-shadow-149", kind: "shadow", theme: "tech", level: "senior", en: "A circuit breaker opens when a dependency fails repeatedly, protecting your service from cascading timeouts.", vi: "Circuit breaker mở khi dependency fail liên tiếp, bảo vệ service khỏi timeout lây lan." },
  { id: "drill-shadow-150", kind: "shadow", theme: "tech", level: "mid", en: "Horizontal scaling adds more instances behind a load balancer, which spreads traffic across all of them.", vi: "Scale ngang thêm instance đằng sau load balancer, phân phối traffic ra tất cả chúng." },
  { id: "drill-shadow-151", kind: "shadow", theme: "design", level: "lead", en: "The main trade-off here is between strong consistency and low latency under write load.", vi: "Trade-off chính ở đây là giữa strong consistency và low latency dưới write load." },
  { id: "drill-shadow-152", kind: "shadow", theme: "design", level: "senior", en: "I would estimate the expected traffic first, then size the database and cache layers accordingly.", vi: "Tôi sẽ ước lượng traffic kỳ vọng trước, rồi sizing database và cache layer tương ứng." },
  { id: "drill-shadow-153", kind: "shadow", theme: "design", level: "senior", en: "If the write path is too slow, I would consider batching or asynchronous processing to absorb the load.", vi: "Nếu write path chậm, tôi batching hoặc async processing để hấp thụ tải." },
  { id: "drill-shadow-154", kind: "shadow", theme: "design", level: "lead", en: "My next step would be to define the data ownership boundaries between services before designing the APIs.", vi: "Bước tiếp theo là định nghĩa data ownership giữa các service trước khi design API." },
  { id: "drill-shadow-155", kind: "shadow", theme: "design", level: "senior", en: "We can improve availability by accepting eventual consistency for non-critical reads.", vi: "Chúng ta có thể cải thiện availability bằng cách chấp nhận eventual consistency cho read không quan trọng." },
  { id: "drill-shadow-156", kind: "shadow", theme: "design", level: "senior", en: "I would prototype the critical path with a simple in-memory cache before adding a distributed one.", vi: "Tôi prototype critical path với in-memory cache đơn giản trước khi thêm distributed cache." },
  { id: "drill-shadow-157", kind: "shadow", theme: "design", level: "senior", en: "Before scaling, I need to measure the actual bottleneck instead of guessing where the problem is.", vi: "Trước khi scale, tôi đo bottleneck thực tế thay vì đoán nơi sự cố." },
  { id: "drill-shadow-158", kind: "shadow", theme: "design", level: "senior", en: "A shared database creates tight coupling, so I prefer each service to own its tables.", vi: "Shared database tạo tight coupling, nên tôi thích mỗi service sở hữu table của mình." },
  { id: "drill-shadow-159", kind: "shadow", theme: "design", level: "senior", en: "I would add a message queue to decouple the order service from the inventory system.", vi: "Tôi thêm message queue để decouple order service khỏi inventory system." },
  { id: "drill-shadow-160", kind: "shadow", theme: "design", level: "senior", en: "The design must handle partial failures gracefully, because networks are not reliable.", vi: "Thiết kế phải xử lý partial failures graceful vì mạng không reliable." },
  { id: "drill-shadow-161", kind: "shadow", theme: "project", level: "senior", en: "I led the rollout of a new feature used by fifty thousand customers.", vi: "Tôi dẫn đầu triển khai tính năng mới được năm mươi nghìn khách hàng sử dụng." },
  { id: "drill-shadow-162", kind: "shadow", theme: "project", level: "senior", en: "My team reduced error rates by sixty percent with better input validation.", vi: "Nhóm tôi giảm tỷ lệ lỗi sáu mươi phần trăm bằng kiểm tra đầu vào tốt hơn." },
  { id: "drill-shadow-163", kind: "shadow", theme: "project", level: "senior", en: "I built a dashboard that showed real time deployment status to stakeholders.", vi: "Tôi xây dựng bảng điều khiển hiển thị trạng thái triển khai thời gian thực cho stakeholder." },
  { id: "drill-shadow-164", kind: "shadow", theme: "project", level: "senior", en: "We cut release time from one week to one day with automation.", vi: "Chúng tôi cắt thời gian phát hành từ một tuần xuống một ngày bằng tự động hóa." },
  { id: "drill-shadow-165", kind: "shadow", theme: "project", level: "senior", en: "I owned the migration of user data to a new database schema.", vi: "Tôi sở hữu việc di chuyển dữ liệu người dùng sang schema cơ sở dữ liệu mới." },
  { id: "drill-shadow-166", kind: "shadow", theme: "project", level: "mid", en: "My team launched the feature two weeks ahead of schedule.", vi: "Nhóm tôi ra mắt tính năng sớm hơn lịch trình hai tuần." },
  { id: "drill-shadow-167", kind: "shadow", theme: "project", level: "senior", en: "We handled a critical bug fix within four hours during production.", vi: "Chúng tôi xử lý sửa lỗi khẩn cấp trong bốn giờ trong production." },
  { id: "drill-shadow-168", kind: "shadow", theme: "behavioral", level: "senior", en: "I admitted a mistake to the team and fixed it the same day.", vi: "Tôi thừa nhận sai lầm trước nhóm và sửa trong cùng ngày." },
  { id: "drill-shadow-169", kind: "shadow", theme: "behavioral", level: "senior", en: "I listened to both sides before deciding how to resolve the conflict.", vi: "Tôi lắng nghe cả hai bên trước khi quyết định cách giải quyết conflict." },
  { id: "drill-shadow-170", kind: "shadow", theme: "behavioral", level: "mid", en: "I gave constructive feedback to a teammate who missed the deadline.", vi: "Tôi phản hồi xây dựng cho đồng đội đã quá hạn nộp công việc." },
  { id: "drill-shadow-171", kind: "shadow", theme: "behavioral", level: "senior", en: "I apologized to the user and explained how we would prevent it.", vi: "Tôi xin lỗi người dùng và giải thích cách chúng ta sẽ ngăn ngừa sự việc lại." },
  { id: "drill-shadow-172", kind: "shadow", theme: "behavioral", level: "senior", en: "I raised a concern with my manager before it became a bigger problem.", vi: "Tôi nêu lo ngại với quản lý trước khi vấn đề trở nên lớn hơn." },
  { id: "drill-shadow-173", kind: "shadow", theme: "behavioral", level: "senior", en: "I mentored a junior engineer who improved code quality in two months.", vi: "Tôi hướng dẫn kỹ sư junior giúp cải thiện chất lượng code trong hai tháng." },
  { id: "drill-shadow-174", kind: "shadow", theme: "negotiation", level: "senior", en: "I would like to know the timeline for the hiring decision.", vi: "Tôi muốn biết lịch trình chốt quyết định tuyển dụng." },
  { id: "drill-shadow-175", kind: "shadow", theme: "smalltalk", level: "mid", en: "Could you tell me about the on call rotation in your team?", vi: "Bạn có thể kể về lịch trực on call trong team bạn không?" },
  { id: "drill-shadow-176", kind: "shadow", theme: "smalltalk", level: "mid", en: "What does a typical day look like for this role?", vi: "Một ngày điển hình cho vị trí này trông như thế nào?" },
  { id: "drill-shadow-177", kind: "shadow", theme: "smalltalk", level: "mid", en: "How does your team celebrate project successes and milestones?", vi: "Team bạn kỷ niệm thành công dự án và mốc quan trọng như thế nào?" },
  { id: "drill-shadow-178", kind: "shadow", theme: "smalltalk", level: "mid", en: "Could you introduce me to the person I would report to?", vi: "Bạn có thể giới thiệu tôi với người tôi sẽ báo cáo không?" },
  { id: "drill-shadow-179", kind: "shadow", theme: "negotiation", level: "mid", en: "I am open to flexible working hours if it helps the team.", vi: "Tôi mở với giờ làm linh hoạt nếu giúp ích cho team." },
  { id: "drill-shadow-180", kind: "shadow", theme: "negotiation", level: "senior", en: "I need to understand the promotion criteria before accepting the offer.", vi: "Tôi cần hiểu tiêu chí thăng tiến trước khi chấp nhận offer." },
  { id: "drill-shadow-181", kind: "shadow", theme: "intro", level: "senior", en: "I am currently a senior backend developer at a fintech company, focusing on scalable payment services.", vi: "Hiện tôi là nhà phát triển backend cấp cao tại một công ty fintech, tập trung vào các dịch vụ thanh toán có khả năng mở rộng." },
  { id: "drill-shadow-182", kind: "shadow", theme: "intro", level: "senior", en: "Most of my experience revolves around Java, Spring Boot, and building microservices for high traffic systems.", vi: "Hầu hết kinh nghiệm của tôi xoay quanh Java, Spring Boot và xây dựng microservices cho các hệ thống lưu lượng cao." },
  { id: "drill-shadow-183", kind: "shadow", theme: "intro", level: "senior", en: "In my current role, I own the entire lifecycle of several critical services, from design to deployment.", vi: "Trong vai trò hiện tại, tôi sở hữu toàn bộ vòng đời của một số dịch vụ quan trọng, từ thiết kế đến triển khai." },
  { id: "drill-shadow-184", kind: "shadow", theme: "intro", level: "senior", en: "I am passionate about building robust and maintainable code that can handle millions of requests daily.", vi: "Tôi đam mê xây dựng mã nguồn mạnh mẽ và dễ bảo trì, có thể xử lý hàng triệu yêu cầu mỗi ngày." },
  { id: "drill-shadow-185", kind: "shadow", theme: "intro", level: "senior", en: "I have about five years of experience working with various database technologies, both SQL and NoSQL.", vi: "Tôi có khoảng năm năm kinh nghiệm làm việc với nhiều công nghệ cơ sở dữ liệu khác nhau, cả SQL và NoSQL." },
  { id: "drill-shadow-186", kind: "shadow", theme: "intro", level: "senior", en: "My daily workflow involves collaborating with product managers to translate requirements into technical specifications.", vi: "Quy trình làm việc hàng ngày của tôi bao gồm cộng tác với các giám đốc sản phẩm để chuyển đổi yêu cầu thành đặc tả kỹ thuật." },
  { id: "drill-shadow-187", kind: "shadow", theme: "intro", level: "senior", en: "I am very comfortable working with distributed systems and understand the challenges of maintaining data consistency.", vi: "Tôi rất thoải mái khi làm việc với các hệ thống phân tán và hiểu được những thách thức trong việc duy trì tính nhất quán của dữ liệu." },
  { id: "drill-shadow-188", kind: "shadow", theme: "intro", level: "senior", en: "I enjoy solving complex backend problems and constantly look for ways to optimize system performance.", vi: "Tôi thích giải quyết các vấn đề backend phức tạp và liên tục tìm cách tối ưu hóa hiệu suất hệ thống." },
  { id: "drill-shadow-189", kind: "shadow", theme: "intro", level: "senior", en: "Besides technical work, I also participate in code reviews and help mentor junior developers in our team.", vi: "Bên cạnh công việc kỹ thuật, tôi cũng tham gia review mã nguồn và giúp hướng dẫn các nhà phát triển trẻ trong nhóm." },
  { id: "drill-shadow-190", kind: "shadow", theme: "intro", level: "senior", en: "I am looking for a new challenge where I can contribute my expertise in Java and cloud technologies.", vi: "Tôi đang tìm kiếm một thử thách mới, nơi tôi có thể đóng góp chuyên môn của mình về Java và các công nghệ đám mây." },
  { id: "drill-shadow-191", kind: "shadow", theme: "tech", level: "senior", en: "Spring Boot's inversion of control helps decouple components and makes the application much easier to test.", vi: "Inversion of Control của Spring Boot giúp tách biệt các thành phần và làm cho ứng dụng dễ kiểm thử hơn nhiều." },
  { id: "drill-shadow-192", kind: "shadow", theme: "tech", level: "senior", en: "JPA simplifies database operations by allowing us to work with Java objects instead of writing raw SQL.", vi: "JPA đơn giản hóa các thao tác cơ sở dữ liệu bằng cách cho phép chúng ta làm việc với các đối tượng Java thay vì viết SQL thuần." },
  { id: "drill-shadow-193", kind: "shadow", theme: "tech", level: "mid", en: "RESTful APIs use standard HTTP methods like GET and POST to enable communication between different web services.", vi: "RESTful API sử dụng các phương thức HTTP tiêu chuẩn như GET và POST để cho phép giao tiếp giữa các dịch vụ web khác nhau." },
  { id: "drill-shadow-194", kind: "shadow", theme: "tech", level: "mid", en: "Unit testing ensures that individual components work as expected and helps prevent bugs during future refactoring.", vi: "Unit test đảm bảo rằng các thành phần riêng lẻ hoạt động như mong đợi và giúp ngăn ngừa lỗi trong quá trình tái cấu trúc sau này." },
  { id: "drill-shadow-195", kind: "shadow", theme: "tech", level: "mid", en: "Integration tests verify that different parts of the system, like the database and API, work together correctly.", vi: "Integration test xác minh rằng các phần khác nhau của hệ thống, như cơ sở dữ liệu và API, hoạt động cùng nhau một cách chính xác." },
  { id: "drill-shadow-196", kind: "shadow", theme: "tech", level: "mid", en: "Docker containers package an application and its dependencies, ensuring it runs consistently across different environments.", vi: "Docker container đóng gói ứng dụng và các phụ thuộc của nó, đảm bảo nó chạy nhất quán trên các môi trường khác nhau." },
  { id: "drill-shadow-197", kind: "shadow", theme: "tech", level: "senior", en: "Kubernetes automates the deployment, scaling, and management of containerized applications in a cloud native environment.", vi: "Kubernetes tự động hóa việc triển khai, mở rộng và quản lý các ứng dụng container trong môi trường cloud native." },
  { id: "drill-shadow-198", kind: "shadow", theme: "tech", level: "senior", en: "A well-designed REST API should be stateless, meaning each request contains all the information needed to process it.", vi: "Một REST API được thiết kế tốt nên là stateless, nghĩa là mỗi yêu cầu chứa tất cả thông tin cần thiết để xử lý nó." },
  { id: "drill-shadow-199", kind: "shadow", theme: "tech", level: "senior", en: "CI/CD pipelines automate the build and deployment process, reducing manual errors and speeding up release cycles.", vi: "Đường ống CI/CD tự động hóa quá trình xây dựng và triển khai, giảm thiểu lỗi thủ công và tăng tốc độ chu kỳ phát hành." },
  { id: "drill-shadow-200", kind: "shadow", theme: "tech", level: "senior", en: "In Spring, a Bean is an object that is instantiated, assembled, and managed by the Spring IoC container.", vi: "Trong Spring, một Bean là một đối tượng được khởi tạo, lắp ráp và quản lý bởi Spring IoC container." },
{ id: "drill-shadow-201", kind: "shadow", theme: "project", level: "senior", en: "The main trade-off was a small increase in storage in exchange for much faster customer searches.", vi: "Đánh đổi chính là tăng nhẹ dung lượng lưu trữ để đổi lấy việc tìm kiếm khách hàng nhanh hơn nhiều." },
{ id: "drill-shadow-202", kind: "shadow", theme: "project", level: "senior", en: "When checkout errors rose during a sale, I checked recent changes and found a bad timeout setting.", vi: "Khi lỗi thanh toán tăng trong đợt khuyến mãi, tôi kiểm tra các thay đổi gần đây và phát hiện cấu hình timeout không phù hợp." },
{ id: "drill-shadow-203", kind: "shadow", theme: "project", level: "senior", en: "We reduced database load by forty percent after batching repeated reads for each customer request.", vi: "Chúng tôi giảm tải cơ sở dữ liệu bốn mươi phần trăm sau khi gom các lần đọc lặp lại trong mỗi yêu cầu khách hàng." },
{ id: "drill-shadow-204", kind: "shadow", theme: "project", level: "senior", en: "We adjusted each service's connection pool after monitoring showed the database was overloaded at peak traffic.", vi: "Chúng tôi điều chỉnh nhóm kết nối của từng service sau khi theo dõi cho thấy cơ sở dữ liệu bị quá tải lúc lưu lượng cao điểm." },
{ id: "drill-shadow-205", kind: "shadow", theme: "project", level: "senior", en: "The p95 response time fell from nine hundred to three hundred milliseconds after we removed a repeated database lookup.", vi: "Độ trễ p95 (mốc mà 95% yêu cầu phản hồi nhanh hơn) giảm từ chín trăm xuống ba trăm mili giây sau khi chúng tôi bỏ một lần tra cứu cơ sở dữ liệu lặp lại." },
{ id: "drill-shadow-206", kind: "shadow", theme: "project", level: "senior", en: "What I did first was limit retries, because repeated attempts were making the outage worse.", vi: "Việc đầu tiên tôi làm là giới hạn số lần thử lại, vì các lần thử liên tục khiến sự cố nghiêm trọng hơn." },
{ id: "drill-shadow-207", kind: "shadow", theme: "project", level: "senior", en: "We moved report generation to a background job, so users no longer waited for a large query.", vi: "Chúng tôi chuyển việc tạo báo cáo sang tác vụ chạy nền, nhờ đó người dùng không còn phải chờ truy vấn lớn." },
{ id: "drill-shadow-208", kind: "shadow", theme: "project", level: "senior", en: "After the release, we watched the error rate and rolled back when it rose above our agreed limit.", vi: "Sau khi phát hành, chúng tôi theo dõi tỷ lệ lỗi và hoàn tác khi chỉ số vượt giới hạn đã thống nhất." },
{ id: "drill-shadow-209", kind: "shadow", theme: "project", level: "senior", en: "I compared the old and new query plans, then added an index that cut the report from twelve seconds to two.", vi: "Tôi so sánh kế hoạch thực thi truy vấn cũ và mới, rồi thêm index giúp giảm thời gian chạy báo cáo từ mười hai giây xuống hai giây." },
{ id: "drill-shadow-210", kind: "shadow", theme: "project", level: "lead", en: "I shared a clear incident timeline with support, helping them answer customer questions while engineers restored service.", vi: "Tôi chia sẻ dòng thời gian sự cố rõ ràng với bộ phận hỗ trợ, giúp họ trả lời khách hàng trong khi kỹ sư khôi phục dịch vụ." },
{ id: "drill-shadow-211", kind: "shadow", theme: "smalltalk", level: "mid", en: "Could you say the last part again, especially the constraint on response time?", vi: "Bạn có thể nhắc lại phần cuối, đặc biệt là giới hạn về thời gian phản hồi không?" },
{ id: "drill-shadow-212", kind: "shadow", theme: "smalltalk", level: "mid", en: "Let me think through the impact on existing customers before I suggest a fix.", vi: "Để tôi suy nghĩ về ảnh hưởng với khách hàng hiện tại trước khi đề xuất cách sửa." },
{ id: "drill-shadow-213", kind: "shadow", theme: "smalltalk", level: "mid", en: "If I understand the question, you want me to compare a quick fix with a lasting solution.", vi: "Nếu tôi hiểu đúng câu hỏi, bạn muốn tôi so sánh cách sửa nhanh với giải pháp lâu dài." },
{ id: "drill-shadow-214", kind: "shadow", theme: "smalltalk", level: "senior", en: "To connect this to my experience, I handled a similar issue during a busy release.", vi: "Để liên hệ với kinh nghiệm của mình, tôi từng xử lý vấn đề tương tự trong một đợt phát hành bận rộn." },
{ id: "drill-shadow-215", kind: "shadow", theme: "smalltalk", level: "mid", en: "Would you mind sharing how the team balances on-call work with planned development?", vi: "Bạn có thể chia sẻ cách nhóm cân bằng công việc trực hệ thống với kế hoạch phát triển không?" },
{ id: "drill-shadow-216", kind: "shadow", theme: "negotiation", level: "senior", en: "Before we wrap up, could you tell me what the next step in the process will be?", vi: "Trước khi kết thúc, bạn có thể cho tôi biết bước tiếp theo của quy trình sẽ là gì không?" },
{ id: "drill-shadow-217", kind: "shadow", theme: "negotiation", level: "mid", en: "Thank you for the thoughtful conversation; I enjoyed hearing how the team approaches reliability.", vi: "Cảm ơn buổi trò chuyện sâu sắc; tôi rất vui khi được nghe cách nhóm tiếp cận độ tin cậy của hệ thống." },
{ id: "drill-shadow-218", kind: "shadow", theme: "negotiation", level: "senior", en: "Could I ask whether this position includes time to mentor engineers and improve shared systems?", vi: "Tôi có thể hỏi vị trí này có dành thời gian hướng dẫn kỹ sư và cải thiện các hệ thống dùng chung không?" },
{ id: "drill-shadow-219", kind: "shadow", theme: "negotiation", level: "senior", en: "I am interested in the role, and I would like to discuss how the level is determined.", vi: "Tôi quan tâm đến vị trí này và muốn trao đổi về cách xác định cấp bậc của vị trí." },
{ id: "drill-shadow-220", kind: "shadow", theme: "negotiation", level: "mid", en: "Thank you again for meeting with me; I look forward to hearing from you.", vi: "Một lần nữa cảm ơn bạn đã gặp tôi; tôi mong sớm nhận được phản hồi." },
{ id: "drill-shadow-221", kind: "shadow", theme: "design", level: "senior", en: "The main trade-off here is between strong consistency and the latency users actually feel.", vi: "Đánh đổi chính ở đây là giữa tính nhất quán mạnh và độ trễ mà người dùng thực sự cảm nhận." },
{ id: "drill-shadow-222", kind: "shadow", theme: "design", level: "senior", en: "I would size this system for ten thousand writes per second and measure again after launch.", vi: "Tôi sẽ thiết kế hệ thống cho mười nghìn lượt ghi mỗi giây, rồi đo lại sau khi ra mắt." },
{ id: "drill-shadow-223", kind: "shadow", theme: "design", level: "lead", en: "My main risk is a slow downstream payment provider, so I would isolate it with a circuit breaker.", vi: "Rủi ro chính của tôi là nhà cung cấp thanh toán phản hồi chậm, nên tôi sẽ cô lập nó bằng circuit breaker." },
{ id: "drill-shadow-224", kind: "shadow", theme: "design", level: "lead", en: "What I would do first is write down the assumptions about traffic, data size, and failure modes.", vi: "Việc đầu tiên tôi làm là viết ra các giả định về lưu lượng, kích thước dữ liệu và các kiểu lỗi." },
{ id: "drill-shadow-225", kind: "shadow", theme: "design", level: "senior", en: "We chose asynchronous messaging because the reporting work does not need to block the user request.", vi: "Chúng tôi chọn messaging bất đồng bộ vì phần việc tạo báo cáo không cần chặn yêu cầu của người dùng." },
{ id: "drill-shadow-226", kind: "shadow", theme: "design", level: "senior", en: "The cost of this design is extra operational work, which I think is justified by the read volume.", vi: "Cái giá của thiết kế này là thêm việc vận hành, mà tôi cho là hợp lý so với lượng đọc." },
{ id: "drill-shadow-227", kind: "shadow", theme: "design", level: "senior", en: "I would partition the data by tenant so a single noisy customer cannot slow down everyone else.", vi: "Tôi sẽ phân vùng dữ liệu theo tenant để một khách hàng dùng nhiều tài nguyên không làm chậm những người còn lại." },
{ id: "drill-shadow-228", kind: "shadow", theme: "design", level: "lead", en: "Before I choose a technology, I want to know the consistency requirement and the recovery time objective.", vi: "Trước khi chọn công nghệ, tôi muốn biết yêu cầu về tính nhất quán và mục tiêu thời gian khôi phục." },
{ id: "drill-shadow-229", kind: "shadow", theme: "design", level: "senior", en: "A queue adds a failure point, so I would monitor its depth and alert on a growing backlog.", vi: "Hàng đợi thêm một điểm có thể lỗi, nên tôi sẽ theo dõi độ sâu hàng đợi và cảnh báo khi tồn đọng tăng." },
{ id: "drill-shadow-230", kind: "shadow", theme: "design", level: "senior", en: "I would start with one service and a single database, then split only when scaling demands it.", vi: "Tôi sẽ bắt đầu với một service và một database, chỉ tách ra khi việc mở rộng thực sự đòi hỏi." },
{ id: "drill-shadow-231", kind: "shadow", theme: "behavioral", level: "lead", en: "I would own the mistake publicly, explain the impact, and describe the guardrail we added afterwards.", vi: "Tôi sẽ nhận lỗi công khai, giải thích ảnh hưởng, và nói về biện pháp bảo vệ chúng tôi thêm sau đó." },
{ id: "drill-shadow-232", kind: "shadow", theme: "behavioral", level: "mid", en: "I once shipped a bug to production, so I told my lead immediately and helped with the rollback.", vi: "Tôi từng đưa một lỗi lên production, nên tôi báo ngay cho lead và cùng xử lý việc hoàn tác." },
{ id: "drill-shadow-233", kind: "shadow", theme: "behavioral", level: "senior", en: "When I disagree with a teammate, I ask questions about the trade-offs instead of rejecting the idea.", vi: "Khi không đồng ý với đồng đội, tôi hỏi về các đánh đổi thay vì bác bỏ ý tưởng." },
{ id: "drill-shadow-234", kind: "shadow", theme: "behavioral", level: "lead", en: "I try to give feedback about the behaviour, not the person, and always suggest a concrete next step.", vi: "Tôi cố gắng phản hồi về hành vi chứ không phải con người, và luôn gợi ý một bước cụ thể tiếp theo." },
{ id: "drill-shadow-235", kind: "shadow", theme: "behavioral", level: "senior", en: "If a teammate is falling behind, I offer help first and only escalate when the deadline is at risk.", vi: "Nếu đồng đội bị chậm, tôi đề nghị giúp trước và chỉ báo lên trên khi deadline có nguy cơ trễ." },
{ id: "drill-shadow-236", kind: "shadow", theme: "behavioral", level: "lead", en: "I once disagreed with my manager, and I supported the final decision once we had discussed it.", vi: "Tôi từng không đồng ý với quản lý, và tôi ủng hộ quyết định cuối cùng sau khi chúng tôi đã trao đổi." },
{ id: "drill-shadow-237", kind: "shadow", theme: "behavioral", level: "senior", en: "What I learned from that failure was to test the rollback path before releasing a risky change.", vi: "Điều tôi học được từ lần thất bại đó là phải kiểm thử đường hoàn tác trước khi phát hành thay đổi rủi ro." },
{ id: "drill-shadow-238", kind: "shadow", theme: "behavioral", level: "senior", en: "I would rather raise a concern early than stay quiet and let the team discover it later.", vi: "Tôi thà nêu lo ngại sớm còn hơn im lặng rồi để cả nhóm phát hiện sau." },
{ id: "drill-shadow-239", kind: "shadow", theme: "behavioral", level: "lead", en: "When I gave hard feedback, I described the specific impact on the team and asked what support was needed.", vi: "Khi đưa phản hồi khó, tôi mô tả ảnh hưởng cụ thể lên nhóm và hỏi cần hỗ trợ gì." },
{ id: "drill-shadow-240", kind: "shadow", theme: "behavioral", level: "mid", en: "I apologize for the confusion in my last message and I will send a corrected version today.", vi: "Tôi xin lỗi vì sự nhầm lẫn trong tin nhắn trước và sẽ gửi bản đã sửa trong hôm nay." },
{ id: "drill-shadow-241", kind: "shadow", theme: "tech", level: "senior", en: "An AI agent repeats a cycle: choose a tool, inspect its result, and stop when its goal is met.", vi: "AI agent lặp một chu trình: chọn công cụ, xem kết quả rồi dừng khi đạt mục tiêu." },
{ id: "drill-shadow-242", kind: "shadow", theme: "tech", level: "senior", en: "Before running a tool, our Java service checks its arguments and the caller's permissions.", vi: "Trước khi chạy công cụ, service Java kiểm tra tham số và quyền của người gọi." },
{ id: "drill-shadow-243", kind: "shadow", theme: "tech", level: "lead", en: "I would expose narrow, read-only tools first, then add write actions only with explicit safeguards.", vi: "Tôi sẽ chỉ mở công cụ đọc với phạm vi hẹp trước, rồi mới thêm thao tác ghi cùng biện pháp bảo vệ rõ ràng." },
{ id: "drill-shadow-244", kind: "shadow", theme: "tech", level: "senior", en: "In Spring AI, a tool call asks application code to run; the model does not execute Java directly.", vi: "Trong Spring AI, lời gọi công cụ yêu cầu code ứng dụng chạy; model không trực tiếp thực thi Java." },
{ id: "drill-shadow-245", kind: "shadow", theme: "tech", level: "senior", en: "MCP is a shared protocol that lets an AI client discover tools offered by another server.", vi: "MCP là giao thức chung giúp AI client tìm các công cụ do server khác cung cấp." },
{ id: "drill-shadow-246", kind: "shadow", theme: "tech", level: "senior", en: "A strict tool-call limit and timeout prevent an agent from retrying forever when a service fails.", vi: "Giới hạn số lần gọi công cụ và timeout chặt chẽ giúp agent không thử lại vô hạn khi service gặp lỗi." },
{ id: "drill-shadow-247", kind: "shadow", theme: "tech", level: "senior", en: "Retrieval augmented generation adds matching documents to a prompt, helping a model answer with current information.", vi: "Retrieval augmented generation đưa tài liệu phù hợp vào prompt, giúp model trả lời dựa trên thông tin cập nhật." },
{ id: "drill-shadow-248", kind: "shadow", theme: "tech", level: "mid", en: "An embedding turns text into a vector, a list of numbers used to find similar meaning.", vi: "Embedding biến văn bản thành vector, một danh sách số dùng để tìm nội dung có ý nghĩa tương tự." },
{ id: "drill-shadow-249", kind: "shadow", theme: "tech", level: "senior", en: "Model output is untrusted, so I validate its structure and check the caller's permissions before changing business data.", vi: "Đầu ra của model không đáng tin, nên tôi kiểm tra cấu trúc và quyền của người gọi trước khi đổi dữ liệu nghiệp vụ." },
{ id: "drill-shadow-250", kind: "shadow", theme: "tech", level: "senior", en: "The context window is the model's token limit, so I keep useful history and retrieved text.", vi: "Context window là giới hạn token của model, nên tôi chỉ giữ lịch sử hữu ích và văn bản đã truy xuất." },
{ id: "drill-shadow-251", kind: "shadow", theme: "design", level: "senior", en: "Cursor pagination returns rows after the last seen key, avoiding the growing cost of large offsets.", vi: "Phân trang bằng con trỏ lấy các dòng sau khóa cuối đã xem, tránh chi phí tăng dần của offset lớn." },
{ id: "drill-shadow-252", kind: "shadow", theme: "design", level: "senior", en: "A read replica can serve more queries, but replication lag may briefly show a user's older data.", vi: "Bản sao chỉ đọc có thể phục vụ thêm truy vấn, nhưng độ trễ sao chép đôi khi khiến người dùng thấy dữ liệu cũ." },
{ id: "drill-shadow-253", kind: "shadow", theme: "design", level: "senior", en: "I would pass one request deadline downstream, so slow calls cannot continue after the user gives up.", vi: "Tôi sẽ truyền thời hạn của yêu cầu xuống các dịch vụ sau, để lời gọi chậm không tiếp tục khi người dùng đã bỏ cuộc." },
{ id: "drill-shadow-254", kind: "shadow", theme: "design", level: "senior", en: "For a safe schema change, I would add a nullable column, deploy compatible code, backfill, and remove old columns last.", vi: "Để đổi schema an toàn, tôi sẽ thêm cột cho phép giá trị null, triển khai code tương thích, bổ sung dữ liệu rồi mới xóa các cột cũ." },
{ id: "drill-shadow-255", kind: "shadow", theme: "design", level: "senior", en: "Kafka preserves order within a partition, so the key affects ordering and can create a hot partition.", vi: "Kafka giữ thứ tự trong một partition, nên key ảnh hưởng thứ tự và có thể tạo partition quá tải." },
{ id: "drill-shadow-256", kind: "shadow", theme: "design", level: "lead", en: "A second region improves disaster recovery, but cross-region writes add latency and need conflict handling.", vi: "Thêm vùng thứ hai cải thiện khôi phục thảm họa, nhưng ghi liên vùng tăng độ trễ và cần xử lý xung đột." },
{ id: "drill-shadow-257", kind: "shadow", theme: "design", level: "lead", en: "I would set a response-time target and track remaining failure budget before investing in more redundancy.", vi: "Tôi sẽ đặt mục tiêu thời gian phản hồi và theo dõi ngân sách lỗi còn lại trước khi đầu tư thêm dự phòng." },
{ id: "drill-shadow-258", kind: "shadow", theme: "design", level: "senior", en: "Separate thread pools isolate slow dependencies, preventing one from exhausting every request thread.", vi: "Các nhóm thread riêng cô lập dependency chậm, ngăn một dependency chiếm hết thread xử lý yêu cầu." },
{ id: "drill-shadow-259", kind: "shadow", theme: "design", level: "senior", en: "Bounded queues can apply backpressure or reject work, protecting memory when producers outpace consumers.", vi: "Queue có giới hạn có thể gây áp lực ngược hoặc từ chối việc mới, bảo vệ bộ nhớ khi bên gửi nhanh hơn bên nhận." },
{ id: "drill-shadow-260", kind: "shadow", theme: "design", level: "senior", en: "A read model speeds up complex screens, but adds storage and means updates may appear later.", vi: "Read model giúp màn hình phức tạp tải nhanh hơn, nhưng tốn thêm lưu trữ và khiến cập nhật có thể xuất hiện muộn." },
);
